mapper.select:
/** * selectOfwkUpcsdClngList : isry.couns.taskwksprt.taskwkandatdmng.mapper.OfwkUpcsdClngSprtMapper : 퇴근미처리소명목록조회 */ SELECT AA.USER_ID AS CNSLTNT_ID , C##RG.DEC_B64(CC.FLNM_ENCPT) AS CNSLTNT_NM , AA.UNOF_YMD AS UNOF_YMD , COUNT(*) OVER() AS TOTAL_COUNT , AA.REG_YN AS REG_YN , ( SELECT A1.CMMNS_CD_VALUE_NM AS CD_NAME FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_NM FROM AYC310 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.USER_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO AND AA.DEL_YN = 'N'
AND AA.USER_ID = #{userId}
AND CC.FLNM_ENCPT = #{userNm}
AND AA.UNOF_YMD BETWEEN TO_DATE(#{bgngYmd},'YYYYMMDD') AND TO_DATE(#{endYmd},'YYYYMMDD')+0.99999
ORDER BY 3 DESC OFFSET #{START_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY /** 페이징 처리 **/

/** * selectOfwkUpcsdClngRegDtl : isry.couns.taskwksprt.taskwkandatdmng.mapper.OfwkUpcsdClngSprtMapper : 퇴근미처리소명등록 상세조회 */ SELECT AA.USER_ID AS CNSLTNT_ID , C##RG.DEC_B64(CC.FLNM_ENCPT) AS CNSLTNT_NM , AA.UNOF_YMD AS UNOF_YMD , AA.UNOF_CS_CN AS LVFFC_CS_CN , AA.ATFINO AS ATFINO , AA.MDFCN_CS_CN AS MDFCN_CS_CN , ( SELECT A1.CMMNS_CD_VALUE_NM AS CD_NAME FROM SAC100 A1 WHERE 1=1 AND A1.CMMNS_CD_ID = 'APRV_STTS_SE_CD' AND A1.CMMNS_CD_VALUE = AA.APRV_STTS_SE_CD ) AS APRV_STTS_SE_NM FROM AYC310 AA , SAA200 BB , SCA100 CC WHERE 1=1 AND AA.USER_ID = BB.USER_ID AND BB.ENFSN_NO = CC.ENFSN_NO AND AA.DEL_YN = 'N'
AND AA.USER_ID = #{userId}
AND AA.UNOF_YMD = #{unofYmd}

mapper.update:
	/**
	*		insertOfwkUpcsdClng : isry.couns.taskwksprt.taskwkandatdmng.mapper.OfwkUpcsdClngSprtMapper : 퇴근미처리소명 등록
	*/
		UPDATE
				AYC310		AA		/** 사이버상담사퇴근관리(퇴근미처리소명) **/
		SET
				DATA_REG_YMD	=	TO_CHAR(SYSDATE,'YYYYMMDD')
			,	UNOF_CS_CN		=	#{lvffcCsCn}
			,	REG_YN			=	'Y'


			         , ATFINO          =   ''



                        ,   ATFINO          =   #{atfino}



			,	LAST_MDFR_ID	=	#{loginId}
			,	LAST_MDFCN_DT	=	SYSDATE
		WHERE	1=1
			AND	AA.USER_ID	=	#{userId}
			AND	AA.UNOF_YMD	=	#{unofYmd}
